H.background();
const r = P.r, h = P.h;
const cam = H.cam3d({ scale: 34, dist: 11, pitch: -0.45, cy: 320 });
cam.yaw = 0.4 * t;
cam.grid(6, 1);
const N = 40;
function ring(y) { const pts = []; for (let i = 0; i <= N; i++) { const a = (i / N) * Math.PI * 2; pts.push([r * Math.cos(a), y, r * Math.sin(a)]); } return pts; }
const yB = -h / 2, yT = h / 2;
cam.path(ring(yB), { color: H.colors.accent, width: 2 });
cam.poly(ring(yT), { fill: "rgba(124,196,255,0.22)", stroke: H.colors.accent, width: 2 });
for (let i = 0; i < N; i += 5) { const a = (i / N) * Math.PI * 2; cam.line([r * Math.cos(a), yB, r * Math.sin(a)], [r * Math.cos(a), yT, r * Math.sin(a)], { color: "rgba(124,196,255,0.5)", width: 1 }); }
cam.line([0, yB, 0], [0, yT, 0], { color: H.colors.warn, width: 2, dash: [4, 4] });
cam.line([0, yB, 0], [r, yB, 0], { color: H.colors.accent2, width: 2 });
const V = Math.PI * r * r * h;
const SA = 2 * Math.PI * r * r + 2 * Math.PI * r * h;
H.text("Cylinder: V = pi r^2 h", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("volume = base circle area times height; side unrolls to a 2 pi r by h rectangle", 24, 52, { color: H.colors.sub, size: 13 });
H.text("r = " + r.toFixed(1) + "   h = " + h.toFixed(1) + "   V = " + V.toFixed(1) + "   SA = " + SA.toFixed(1), 24, 74, { color: H.colors.accent2, size: 13 });
